contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public {
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        require(caller == ownerBefore, "only owner path");

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        assert(!reverted && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

